with kept_keys as (select firmware, device_code from device_readings except all select firmware, device_code from device_readings where pressure is null), kept_rows as (select s.* from device_readings s join kept_keys k on s.firmware = k.firmware and s.device_code = k.device_code) select device_code, reading_ts, temp_c, humidity, pressure, firmware from kept_rows order by temp_c nulls first;
